function observationsList(){const rows=state.observations.filter(o=>o.project_id===state.project),counts={open:rows.filter(o=>o.status==='open').length,pending:rows.filter(o=>o.status==='pending_verification').length,closed:rows.filter(o=>o.status==='closed').length};frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Safety Observations','Observaciones de seguridad')}</h1><p>${tr('Track hazards, corrections and Safety verification.','Controla peligros, correcciones y verificación de Safety.')}</p></div><button id="obs-new">+ ${tr('New Observation','Nueva observación')}</button></div><div class="obs-summary" role="tablist" aria-label="${tr('Observation status','Estado de observaciones')}"><button class="summary-chip all active" data-status="all" role="tab"><span class="status-mark">●</span><span class="status-copy"><small>${tr('All','Todas')}</small><strong>${rows.length}</strong></span></button><button class="summary-chip open" data-status="open" role="tab"><span class="status-mark">!</span><span class="status-copy"><small>${tr('Open','Abiertas')}</small><strong>${counts.open}</strong></span></button><button class="summary-chip progress" data-status="pending_verification" role="tab"><span class="status-mark">↻</span><span class="status-copy"><small>${tr('In Progress','En proceso')}</small><strong>${counts.pending}</strong></span></button><button class="summary-chip closed" data-status="closed" role="tab"><span class="status-mark">✓</span><span class="status-copy"><small>${tr('Closed','Cerradas')}</small><strong>${counts.closed}</strong></span></button></div><div class="obs-tools"><input id="obs-search" type="search" placeholder="${tr('Search area, category or observation...','Buscar área, categoría u observación...')}"><select id="obs-priority"><option value="all">${tr('All priorities','Todas las prioridades')}</option><option value="high">${tr('High priority','Prioridad alta')}</option><option value="medium">${tr('Medium priority','Prioridad media')}</option><option value="low">${tr('Low priority','Prioridad baja')}</option></select></div><div id="obs-list" class="obs-list"></div></section>`);let status='all';const paint=()=>{const q=document.querySelector('#obs-search').value.trim().toLowerCase(),priority=document.querySelector('#obs-priority').value,list=document.querySelector('#obs-list');const filtered=rows.filter(o=>(status==='all'||o.status===status)&&(priority==='all'||o.priority===priority)&&(!q||[o.area,o.category,o.description,o.assignee?.name].some(v=>String(v||'').toLowerCase().includes(q))));list.innerHTML=filtered.length?filtered.map(o=>`<button class="obs-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${o.status==='pending_verification'?tr('IN PROGRESS','EN PROCESO'):o.status==='closed'?tr('CLOSED','CERRADA'):tr('OPEN','ABIERTA')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No observations found','No se encontraron observaciones')}</strong><p>${tr('Change the filters or create a new observation.','Cambia los filtros o crea una nueva observación.')}</p></div>`;list.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})};document.querySelector('#obs-new').onclick=()=>navigate('new');document.querySelector('#obs-search').oninput=paint;document.querySelector('#obs-priority').onchange=paint;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('active',x===b));paint()});paint()}
function correctionsList(){const rows=state.observations.filter(o=>o.project_id===state.project&&o.status==='pending_verification');frame(`<section class="observations-shell"><div class="section-heading"><div><h1>${tr('Corrections','Correcciones')}</h1><p>${tr('Review completed corrective actions before final closure.','Revisa las acciones correctivas completadas antes del cierre final.')}</p></div></div><div class="review-banner"><strong>${rows.length}</strong><span>${tr('Awaiting Safety review','Esperando revisión de Safety')}</span></div><div class="obs-list">${rows.length?rows.map(o=>`<button class="obs-card correction-card" data-id="${o.id}"><div class="obs-card-top"><span class="badge ${esc(o.priority)}">${o.priority==='high'?tr('HIGH','ALTA'):o.priority==='medium'?tr('MEDIUM','MEDIA'):tr('LOW','BAJA')}</span><span class="obs-status">${tr('READY FOR REVIEW','LISTA PARA REVISIÓN')}</span></div><h3>${esc(o.area)}</h3><p class="obs-category">${esc(o.category)}</p><p>${esc(o.description)}</p><div class="obs-meta"><span>${esc(o.assignee?.name||tr('Unassigned','Sin asignar'))}</span><span>${fmt(o.created_at)}</span></div></button>`).join(''):`<div class="empty-state"><strong>${tr('No corrections awaiting review','No hay correcciones esperando revisión')}</strong><p>${tr('Completed corrections will appear here automatically.','Las correcciones completadas aparecerán aquí automáticamente.')}</p></div>`}</div></section>`);document.querySelectorAll('[data-id]').forEach(el=>el.onclick=async()=>{state.detail=el.dataset.id;await markViewed(state.detail);navigate('detail',state.detail)})}
